'use strict';
const adventures={
 tristeza:{label:'Tristeza',title:'Un lugar al lado de Tilo',story:['Tilo había preparado un rincón para jugar con una amiga. Pero hoy ella no podía venir. Miró el lugar vacío y se quedó callado.','Una mariposa se acercó. «¿Querés que me quede un ratito?», preguntó. Tilo asintió. No tenía ganas de hablar todavía.','Se sentaron junto a la flor. La tristeza seguía allí, pero Tilo ya no estaba solo. «Gracias por acompañarme», dijo bajito.'],options:['Preguntar si quiere compañía.','Ofrecer escuchar, sin apurarlo.','Dejarle espacio y decirle que estamos cerca.'],feedback:['Podemos preguntar y aceptar su respuesta. A veces ayuda que alguien simplemente se quede.','Escuchar también es acompañar. No hace falta encontrar una solución enseguida.','Dar espacio puede ser una forma de cuidar. Podemos volver a preguntar más tarde.'],questions:['¿Qué parte del cuento les llamó la atención?','Cuando estamos tristes, ¿preferimos compañía, silencio o algo distinto?','¿Cómo podemos preguntar qué necesita alguien de la familia?'],offline:'Busquen un lugar cómodo. Cada persona puede pedir compañía, silencio o una mano cerca. Un abrazo también vale, si ambos lo quieren.'},
 enojo:{label:'Enojo',title:'La torre que se cayó',story:['Tilo había apilado unas piedras con mucho cuidado. Cuando iba a poner la última, la torre se cayó. «¡No puede ser!», exclamó.','Sintió las patas tensas y ganas de empujar todo. Dio un paso atrás. «Estoy enojado. Necesito una pausa», dijo.','Después de un rato, llamó a una amiga. «¿Me ayudás a hacer una base más ancha?». Podían volver a intentarlo cuando Tilo estuviera listo.'],options:['Hacer una pausa en un lugar tranquilo.','Decir con palabras lo que necesita.','Pedir ayuda cuando esté listo.'],feedback:['Una pausa puede darnos tiempo para elegir qué hacer. No hay que resolverlo todo ahora.','Podemos sentir enojo y cuidar a los demás. Decir «necesito espacio» es una opción.','Pedir ayuda puede abrir otra manera de intentarlo. También vale dejarlo para después.'],questions:['¿Qué pasó antes de que Tilo se enojara?','¿Qué les ayuda a hacer una pausa sin lastimarse ni lastimar?','¿Qué frase podemos usar en casa para pedir un momento?'],offline:'Inventen una señal familiar para pedir una pausa. Pruébenla juntos y acuerden cómo respetarla.'},
 alegria:{label:'Alegría',title:'Una flor para compartir',story:['Una mañana, Tilo encontró una flor nueva cerca del camino. Tenía pétalos amarillos que brillaban al sol. «¡Miren lo que encontré!», dijo.','Llamó a sus amigos. Uno quería saltar y otro prefería mirar la flor en silencio. Cada uno disfrutaba a su manera.','Tilo sonrió. No necesitaban sentir lo mismo ni festejar igual. Era lindo compartir aquel pequeño descubrimiento.'],options:['Contar qué le gustó del descubrimiento.','Invitar a mirar sin obligar a festejar.','Escuchar qué disfruta cada uno.'],feedback:['Compartir un detalle lindo puede abrir una conversación. Puede ser algo muy pequeño.','Una invitación deja lugar a decir sí o no. Podemos disfrutar de maneras diferentes.','La alegría no se ve igual en todos. Escuchar nos ayuda a conocer esas diferencias.'],questions:['¿Qué detalle pequeño les dio alegría hoy?','¿Cómo se nota la alegría en cada uno de ustedes?','¿Qué les gustaría compartir juntos esta semana?'],offline:'Miren alrededor y elijan algo pequeño que les guste. Por turnos, cuenten por qué lo eligieron. También se puede señalar sin hablar.'}
};
let state={emotion:null,step:0,page:0,choice:null,question:0};
const home=document.querySelector('#home'),journey=document.querySelector('#journey'),activity=document.querySelector('#activity');
function start(emotion){if(!Object.hasOwn(adventures,emotion))throw new Error('Emoción no válida');state={emotion,step:0,page:0,choice:null,question:0};home.hidden=true;journey.hidden=false;document.querySelector('#emotion-label').textContent=adventures[emotion].label;render();}
function goHome(){state={emotion:null,step:0,page:0,choice:null,question:0};home.hidden=false;journey.hidden=true;document.querySelector('[data-emotion]').focus();}
function render(){const a=adventures[state.emotion];document.querySelectorAll('.steps li').forEach((li,i)=>{li.className=i===state.step?'active':i<state.step?'done':'';if(i===state.step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});
 if(state.step===0){activity.innerHTML=`<span class="eyebrow">UN CUENTO PARA LEER JUNTOS</span><h2 id="journey-title" tabindex="-1">${a.title}</h2><p class="story-text">${a.story[state.page]}</p><p class="progress-note">Página ${state.page+1} de ${a.story.length}</p><div class="actions">${state.page?'<button class="secondary" data-action="previous">Anterior</button>':''}<button class="primary" data-action="next">${state.page<2?'Seguir el cuento':'Vamos a jugar'}</button></div>`;}
 else if(state.step===1){activity.innerHTML=`<span class="eyebrow">EL JUEGO DE ACOMPAÑAR</span><h2 id="journey-title" tabindex="-1">¿Qué podrían probar?</h2><p class="body-copy">Elijan una idea para Tilo. Hay distintas maneras de acompañar; conversen cuál les gustaría probar.</p><div class="game-options">${a.options.map((t,i)=>`<button class="game-option ${state.choice===i?'selected':''}" data-choice="${i}" aria-pressed="${state.choice===i}">${t}</button>`).join('')}</div><div aria-live="polite">${state.choice!==null?`<p class="feedback">${a.feedback[state.choice]}</p>`:''}</div><div class="actions"><button class="secondary" data-action="story">Volver al cuento</button><button class="primary" data-action="talk" ${state.choice===null?'disabled':''}>Conversemos</button></div>`;}
 else if(state.step===2){activity.innerHTML=`<span class="eyebrow">UNA PREGUNTA, MUCHAS RESPUESTAS</span><h2 id="journey-title" tabindex="-1">Ahora les toca a ustedes.</h2><p class="body-copy">Hablen por turnos, sin apuro. Escuchar o pasar también vale.</p><p class="question">${a.questions[state.question]}</p><p class="progress-note">Pregunta ${state.question+1} de 3 · No hace falta escribir nada.</p><div class="actions">${state.question?'<button class="secondary" data-action="prev-question">Anterior</button>':''}<button class="primary" data-action="next-question">${state.question<2?'Otra pregunta':'Cerrar nuestro ratito'}</button></div>`;}
 else{activity.innerHTML=`<span class="eyebrow">PARA SEGUIR FUERA DE LA PANTALLA</span><h2 id="journey-title" tabindex="-1">Gracias por compartir.</h2><div class="finished"><strong>Un pequeño momento juntos</strong><p>${a.offline}</p></div><p class="body-copy">Pueden cerrar la pantalla y continuar a su ritmo.</p><div class="actions"><button class="primary" data-action="home">Elegir otra emoción</button><button class="secondary" data-action="restart">Repetir esta aventura</button></div>`;}
 document.querySelector('#journey-title').focus({preventScroll:true});}
document.querySelectorAll('[data-emotion]').forEach(b=>b.addEventListener('click',()=>start(b.dataset.emotion)));
document.querySelector('#back-home').addEventListener('click',goHome);
activity.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.choice!==undefined){state.choice=Number(b.dataset.choice);render();activity.querySelector(`[data-choice="${state.choice}"]`).focus({preventScroll:true});return;}switch(b.dataset.action){case'previous':state.page=Math.max(0,state.page-1);break;case'next':if(state.page<2)state.page++;else state.step=1;break;case'story':state.step=0;break;case'talk':if(state.choice===null)return;state.step=2;break;case'prev-question':state.question=Math.max(0,state.question-1);break;case'next-question':if(state.question<2)state.question++;else state.step=3;break;case'home':goHome();return;case'restart':start(state.emotion);return;default:return;}render();});
const dialog=document.querySelector('#adult-dialog');document.querySelector('#adults').onclick=()=>dialog.showModal();document.querySelector('#close-dialog').onclick=()=>dialog.close();document.querySelector('#return-play').onclick=()=>dialog.close();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_tilo_adventure',description:'Inicia un cuento y una actividad familiar para la emoción elegida. Reinicia el recorrido actual.',inputSchema:{type:'object',properties:{emotion:{type:'string',enum:['tristeza','enojo','alegria']}},required:['emotion'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||typeof input.emotion!=='string')throw new Error('Indicá una emoción válida');start(input.emotion);return{emotion:state.emotion,stage:'cuento',page:1};}})).catch(()=>{});}catch{}}
